import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Days Asia- MicroCeph- Flexible Ceph Orchestration","description":"","frontmatter":{"title":"Ceph Days Asia- MicroCeph- Flexible Ceph Orchestration","date":"2024-10-04T00:00:00.000Z","updated":"2024-10-04T00:00:00.000Z","tags":["Ceph微云","分布式存储","Ceph管理","Ceph部署","Ceph架构"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_Days_Asia_-_MicroCeph_-_Flexible_Ceph_Orchestration.md","filePath":"posts/2024/Ceph_Days_Asia_-_MicroCeph_-_Flexible_Ceph_Orchestration.md","lastUpdated":1780459816000}'),r={name:"posts/2024/Ceph_Days_Asia_-_MicroCeph_-_Flexible_Ceph_Orchestration.md"};function o(s,l,h,n,p,_){return e(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph微云与灵活ceph编排功能介绍" tabindex="-1">会议主题：Ceph微云与灵活Ceph编排功能介绍 <a class="header-anchor" href="#会议主题-ceph微云与灵活ceph编排功能介绍" aria-label="Permalink to &quot;会议主题：Ceph微云与灵活Ceph编排功能介绍&quot;">​</a></h4><h4 id="会议时间-具体日期" tabindex="-1">会议时间：[具体日期] <a class="header-anchor" href="#会议时间-具体日期" aria-label="Permalink to &quot;会议时间：[具体日期]&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>会议目的</strong>：</p><ul><li>介绍Ceph微云（MicroCeph）的最新功能，特别是其灵活编排特性。</li><li>探讨Ceph的部署、配置和管理，以及如何通过微云简化操作流程。</li></ul></li><li><p><strong>会议议程</strong>：</p><ul><li>介绍Ceph微云的基本概念和部署优势。</li><li>讨论网络配置和RBD客户端的配置。</li><li>深入讲解微云的架构和功能，包括其独立性、版本更新和配置管理。</li><li>展示单节点Ceph集群的部署和配置过程，包括服务管理和网络隔离。</li><li>讨论Ceph的远程复制功能开发进展。</li></ul></li><li><p><strong>关键讨论点</strong>：</p><ul><li><strong>微云介绍</strong>： <ul><li>微云作为运行在主机上的隔离容器，不依赖主机提供任何依赖。</li><li>支持版本更新，从Edge到Stable的版本升级。</li></ul></li><li><strong>微云的必要性</strong>： <ul><li>简化Ceph集群的部署和操作，降低技术门槛。</li><li>便于开发和培训，支持个人电脑上的快速部署。</li></ul></li><li><strong>微云的设计哲学</strong>： <ul><li>默认配置：基于标准、合理的默认配置，用户可根据需要自定义。</li><li>简化部署：通过简单的命令即可完成Ceph集群的部署。</li></ul></li><li><strong>微云的部署过程</strong>： <ul><li>安装snap包，启动集群管理器和MDS服务，添加磁盘即可完成部署。</li></ul></li><li><strong>微云的网络配置</strong>： <ul><li>支持为公共网络和私有网络配置不同的子网。</li></ul></li><li><strong>微云的服务管理</strong>： <ul><li>支持在任意节点上启动和管理服务，如RGW服务。</li></ul></li><li><strong>微云的配置管理</strong>： <ul><li>支持全局和特定主机的配置，自动应用配置并重启相关服务。</li></ul></li></ul></li><li><p><strong>演示内容</strong>：</p><ul><li>展示了一个单节点Ceph集群的部署和配置过程。</li><li>演示了如何禁用复制功能，配置RGW服务，并通过S3 API进行操作。</li></ul></li><li><p><strong>正在进行的开发工作</strong>：</p><ul><li><strong>远程复制功能</strong>： <ul><li>正在开发远程复制功能，简化配置和管理流程。</li><li>使用类似添加新节点的令牌机制来实现远程集群的通信。</li></ul></li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续开发和完善远程复制功能。</li><li>提供更多关于微云的文档和教程，帮助用户更好地理解和使用Ceph。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><ul><li>感谢所有参会人员的参与和支持，希望大家继续关注Ceph的发展和更新。</li></ul>',10)])])}const d=i(r,[["render",o]]);export{c as __pageData,d as default};
